extension Texts {
    // Quotations from the Stoics' own works; Spanish wording follows published translations.
    // stoicEs[i] and stoicEn[i] are the same passage.
    static let stoicEs = [
        Quote(text: "No es que tengamos poco tiempo, sino que perdemos mucho.", source: "Séneca, Sobre la brevedad de la vida, 1"),
        Quote(text: "La vida se divide en tres tiempos: el que fue, el que es y el que será. De estos, el presente es breve; el futuro, dudoso; el pasado, cierto.", source: "Séneca, Sobre la brevedad de la vida, 10"),
        Quote(text: "Mientras se difiere, la vida transcurre.", source: "Séneca, Cartas de un estoico, 1"),
        Quote(text: "No es pobre el que tiene poco, sino el que ansía más.", source: "Séneca, Cartas de un estoico, 2"),
        Quote(text: "Nadie puede tener una vida tranquila si piensa demasiado en alargarla.", source: "Séneca, Cartas de un estoico, 4"),
        Quote(text: "Cesarás de temer cuando ceses de esperar.", source: "Séneca, Cartas de un estoico, 5"),
        Quote(text: "Recógete en ti mismo cuando puedas, busca a quienes pueden hacerte mejor, y recibe también a quienes puedas tú mejorar.", source: "Séneca, Cartas de un estoico, 7"),
        Quote(text: "Los hombres, mientras enseñan, aprenden.", source: "Séneca, Cartas de un estoico, 7"),
        Quote(text: "Si quieres ser amado, ama.", source: "Séneca, Cartas de un estoico, 9"),
        Quote(text: "Vive con los hombres como si Dios te viera; habla con Dios como si los hombres te escucharan.", source: "Séneca, Cartas de un estoico, 10"),
        Quote(text: "Más son las cosas que nos atemorizan que las que nos oprimen, y más a menudo padecemos por aprensión que por realidad.", source: "Séneca, Cartas de un estoico, 13"),
        Quote(text: "Si no quieres que un hombre flaquee cuando llegue la crisis, ejercítalo antes de que llegue.", source: "Séneca, Cartas de un estoico, 18"),
        Quote(text: "Una deuda pequeña hace de un hombre tu deudor; una grande, tu enemigo.", source: "Séneca, Cartas de un estoico, 19"),
        Quote(text: "Los hombres no se preocupan de vivir noblemente, sino de vivir mucho, aunque vivir noblemente está al alcance de todos y vivir mucho no está en poder de nadie.", source: "Séneca, Cartas de un estoico, 22"),
        Quote(text: "Hay que cambiar de alma, no de clima.", source: "Séneca, Cartas de un estoico, 28"),
        Quote(text: "Un gran piloto sabe navegar aun con la vela rota.", source: "Séneca, Cartas de un estoico, 30"),
        Quote(text: "Antes de envejecer procuré vivir bien; ahora que soy viejo, procuraré morir bien; y morir bien es morir de buen grado.", source: "Séneca, Cartas de un estoico, 61"),
        Quote(text: "El sabio vive tanto como debe, no tanto como puede.", source: "Séneca, Cartas de un estoico, 70"),
        Quote(text: "Cuando uno no sabe a qué puerto se dirige, ningún viento le es favorable.", source: "Séneca, Cartas de un estoico, 71"),
        Quote(text: "La recompensa de una buena acción es haberla hecho.", source: "Séneca, Cartas de un estoico, 81"),
        Quote(text: "Es áspero el camino que conduce a las alturas de la grandeza.", source: "Séneca, Cartas de un estoico, 84"),
        Quote(text: "Se duele más de lo necesario quien se duele antes de lo necesario.", source: "Séneca, Cartas de un estoico, 98"),
        Quote(text: "No nos atrevemos a muchas cosas porque son difíciles, pero son difíciles porque no nos atrevemos a hacerlas.", source: "Séneca, Cartas de un estoico, 104"),
        Quote(text: "Nadie puede llevar la máscara durante mucho tiempo.", source: "Séneca, Sobre la clemencia, I.1"),
        Quote(text: "Un buen juez condena los actos reprobables, pero no los odia.", source: "Séneca, Sobre la ira, I.16"),
        Quote(text: "Mientras nos encontremos entre los hombres, practiquemos la humanidad.", source: "Séneca, Sobre la ira, III.43"),
        Quote(text: "Quien teme a la muerte nunca hará nada propio de un hombre vivo.", source: "Séneca, Sobre la tranquilidad del ánimo, 11"),
        Quote(text: "El fuego prueba el oro; la desgracia, a los hombres fuertes.", source: "Séneca, Sobre la providencia, 5"),
        Quote(text: "Tu tiempo tiene un límite fijado y, si no lo aprovechas para alcanzar la serenidad, pasará, y ya no volverá.", source: "Marco Aurelio, Meditaciones, II.4"),
        Quote(text: "Aunque debieras vivir tres mil años y aun diez veces otros tantos, acuérdate siempre que no se pierde otra vida que la que se vive y que sólo se vive la que se pierde.", source: "Marco Aurelio, Meditaciones, II.14"),
        Quote(text: "Hay que ser derecho, no enderezado.", source: "Marco Aurelio, Meditaciones, III.5"),
        Quote(text: "Nunca estimes como útil para ti lo que un día te obligue a romper tu palabra o a perder el respeto de ti mismo.", source: "Marco Aurelio, Meditaciones, III.7"),
        Quote(text: "En ninguna parte puede hallar el hombre un retiro tan apacible y tranquilo como en la intimidad de su alma.", source: "Marco Aurelio, Meditaciones, IV.3"),
        Quote(text: "El mundo no es más que transformación, y la vida, opinión solamente.", source: "Marco Aurelio, Meditaciones, IV.3"),
        Quote(text: "No actúes en la idea de que vas a vivir diez mil años. La necesidad ineludible pende sobre ti. Mientras vives, mientras es posible, sé virtuoso.", source: "Marco Aurelio, Meditaciones, IV.17"),
        Quote(text: "El tiempo es como un río, formado por los hechos, que adquiere violenta corriente. Apenas se advierte uno, cuando otro ocupa su lugar, para dejar enseguida paso al que le sigue.", source: "Marco Aurelio, Meditaciones, IV.43"),
        Quote(text: "Tal como sean tus pensamientos habituales, así será tu mente, porque el alma se tiñe del color de sus pensamientos.", source: "Marco Aurelio, Meditaciones, V.16"),
        Quote(text: "A nadie le sucede nada que no esté por naturaleza capacitado para soportar.", source: "Marco Aurelio, Meditaciones, V.18"),
        Quote(text: "Lo que no es dañino a la ciudad tampoco daña al ciudadano.", source: "Marco Aurelio, Meditaciones, V.22"),
        Quote(text: "El mejor modo de vengar la injuria es no parecerse al que la infirió.", source: "Marco Aurelio, Meditaciones, VI.6"),
        Quote(text: "Si algo te resulta difícil de realizar, no pienses que es imposible para el hombre; y si algo es posible y propio del hombre, piensa que también está a tu alcance.", source: "Marco Aurelio, Meditaciones, VI.19"),
        Quote(text: "Asia y Europa, rincones del mundo; todo el océano, una gota del universo; el Atos, un terrón del universo; todo el presente, un instante en la eternidad.", source: "Marco Aurelio, Meditaciones, VI.36"),
        Quote(text: "Adáptate a las cosas que te han tocado en suerte; y a los hombres con quienes te ha tocado vivir, ámalos, pero de verdad, sinceramente.", source: "Marco Aurelio, Meditaciones, VI.39"),
        Quote(text: "Lo que no es útil al enjambre tampoco lo es para la abeja.", source: "Marco Aurelio, Meditaciones, VI.54"),
        Quote(text: "No te inquiete el futuro. Llegarás a él, si es preciso, con la misma razón de la que ahora te sirves para el presente.", source: "Marco Aurelio, Meditaciones, VII.8"),
        Quote(text: "Pronto lo habrás olvidado todo; pronto todos te habrán olvidado.", source: "Marco Aurelio, Meditaciones, VII.21"),
        Quote(text: "Mira bien dentro de ti. Allí está la fuente del bien, jamás exhausta si la vas ahondando.", source: "Marco Aurelio, Meditaciones, VII.59"),
        Quote(text: "El arte de vivir se asemeja más a la lucha que a la danza en lo que se refiere a estar firmemente dispuesto a hacer frente a los accidentes incluso imprevistos.", source: "Marco Aurelio, Meditaciones, VII.61"),
        Quote(text: "Es ridículo no intentar evitar tu propia maldad, lo cual es posible, y en cambio intentar evitar la de los demás, lo cual es imposible.", source: "Marco Aurelio, Meditaciones, VII.71"),
        Quote(text: "Los hombres fueron hechos los unos para los otros, así que, instrúyelos o sopórtalos.", source: "Marco Aurelio, Meditaciones, VIII.59"),
        Quote(text: "No discutas más sobre cómo debe ser el hombre bueno, sino sé tú uno.", source: "Marco Aurelio, Meditaciones, X.16"),
        Quote(text: "Si no conviene, no lo hagas; si no es verdad, no lo digas.", source: "Marco Aurelio, Meditaciones, XII.17"),
        Quote(text: "Olvidaste también que todo es opinión; que cada uno vive únicamente el momento presente, y eso es lo único que pierde.", source: "Marco Aurelio, Meditaciones, XII.26"),
        Quote(text: "Lo que perturba al hombre no son las cosas, sino los juicios relativos a las cosas.", source: "Epicteto, Enquiridión, 5"),
        Quote(text: "Acusar a otros de los propios males es propio del ignorante; acusarse a sí mismo, del que empieza a instruirse; y no acusar ni a otro ni a sí mismo, del que ya está instruido.", source: "Epicteto, Enquiridión, 5"),
        Quote(text: "Nunca pidas que las cosas se hagan como quieres, mas procura quererlas como ellas se hacen. Por este medio todo te sucederá como lo deseas.", source: "Epicteto, Enquiridión, 8"),
        Quote(text: "Recuerda que no te ultraja quien te insulta o te golpea, sino tu opinión de que esas cosas son ultrajantes.", source: "Epicteto, Enquiridión, 20"),
        Quote(text: "Todo tiene dos asas: una por la que se la puede llevar y otra por la que no se puede.", source: "Epicteto, Enquiridión, 43"),
        Quote(text: "Ninguna cosa grande se produce de repente, como tampoco el racimo de uvas o el higo. Si me dices que quieres un higo, te responderé que hace falta tiempo.", source: "Epicteto, Disertaciones, I.15"),
        Quote(text: "Ejercítate, por los dioses, en las cosas pequeñas, y desde ahí pasa a las mayores.", source: "Epicteto, Disertaciones, I.18"),
        Quote(text: "El dolor y la muerte no son terribles, sino el miedo al dolor o a la muerte.", source: "Epicteto, Disertaciones, II.1"),
        Quote(text: "¿Cuál es la primera tarea del que filosofa? Desprenderse de la presunción, porque es imposible empezar a aprender lo que uno cree que ya sabe.", source: "Epicteto, Disertaciones, II.17"),
        Quote(text: "Todo hábito y facultad se mantiene y se acrecienta con las acciones correspondientes: el de caminar, caminando; el de correr, corriendo. Si quieres leer bien, lee; si escribir, escribe.", source: "Epicteto, Disertaciones, II.18"),
        Quote(text: "Primero di quién quieres ser; después haz lo que tengas que hacer.", source: "Epicteto, Disertaciones, III.23"),
        Quote(text: "Poco hace falta para arruinarlo y trastornarlo todo: basta un ligero extravío de la razón.", source: "Epicteto, Disertaciones, IV.3"),
    ]

    // English quotations from public-domain translations; the translator is named where the wording was confirmed.
    static let stoicEn = [
        Quote(text: "It is not that we have a short space of time, but that we waste much of it. Life is long enough.", source: "Seneca, On the Shortness of Life, 1 (tr. Basore)"),
        Quote(text: "Life is divided into three periods, that which has been, that which is, that which will be. Of these the present time is short, the future is doubtful, the past is certain.", source: "Seneca, On the Shortness of Life, 10 (tr. Basore)"),
        Quote(text: "While we are postponing, life speeds by.", source: "Seneca, Letters from a Stoic, 1 (tr. Gummere)"),
        Quote(text: "It is not the man who has too little, but the man who craves more, that is poor.", source: "Seneca, Letters from a Stoic, 2 (tr. Gummere)"),
        Quote(text: "No man can have a peaceful life who thinks too much about lengthening it.", source: "Seneca, Letters from a Stoic, 4 (tr. Gummere)"),
        Quote(text: "Cease to hope, and you will cease to fear.", source: "Seneca, Letters from a Stoic, 5 (tr. Gummere)"),
        Quote(text: "Withdraw into yourself, as far as you can. Associate with those who will make a better man of you. Welcome those whom you yourself can improve.", source: "Seneca, Letters from a Stoic, 7 (tr. Gummere)"),
        Quote(text: "Men learn while they teach.", source: "Seneca, Letters from a Stoic, 7 (tr. Gummere)"),
        Quote(text: "If you would be loved, love.", source: "Seneca, Letters from a Stoic, 9 (tr. Gummere)"),
        Quote(text: "Live among men as if God beheld you; speak with God as if men were listening.", source: "Seneca, Letters from a Stoic, 10 (tr. Gummere)"),
        Quote(text: "There are more things, Lucilius, likely to frighten us than there are to crush us; we suffer more often in imagination than in reality.", source: "Seneca, Letters from a Stoic, 13 (tr. Gummere)"),
        Quote(text: "If you would not have a man flinch when the crisis comes, train him before it comes.", source: "Seneca, Letters from a Stoic, 18 (tr. Gummere)"),
        Quote(text: "A trifling debt makes a man your debtor; a large one makes him an enemy.", source: "Seneca, Letters from a Stoic, 19 (tr. Gummere)"),
        Quote(text: "Men do not care how nobly they live, but only how long, although it is within the reach of every man to live nobly, but within no man's power to live long.", source: "Seneca, Letters from a Stoic, 22 (tr. Gummere)"),
        Quote(text: "You need a change of soul rather than a change of climate.", source: "Seneca, Letters from a Stoic, 28 (tr. Gummere)"),
        Quote(text: "A great pilot can sail even when his canvas is rent.", source: "Seneca, Letters from a Stoic, 30 (tr. Gummere)"),
        Quote(text: "Before I became old I tried to live well; now that I am old, I shall try to die well; but dying well means dying gladly.", source: "Seneca, Letters from a Stoic, 61 (tr. Gummere)"),
        Quote(text: "The wise man will live as long as he ought, not as long as he can.", source: "Seneca, Letters from a Stoic, 70 (tr. Gummere)"),
        Quote(text: "Our plans miscarry because they have no aim. When a man does not know what harbour he is making for, no wind is the right wind.", source: "Seneca, Letters from a Stoic, 71 (tr. Gummere)"),
        Quote(text: "The reward for a good deed is to have done it.", source: "Seneca, Letters from a Stoic, 81"),
        Quote(text: "It is a rough road that leads to the heights of greatness.", source: "Seneca, Letters from a Stoic, 84 (tr. Gummere)"),
        Quote(text: "He suffers more than is necessary, who suffers before it is necessary.", source: "Seneca, Letters from a Stoic, 98"),
        Quote(text: "It is not because things are difficult that we do not dare; it is because we do not dare that they are difficult.", source: "Seneca, Letters from a Stoic, 104"),
        Quote(text: "No one can wear a mask for long.", source: "Seneca, On Clemency, I.1 (tr. Basore)"),
        Quote(text: "A good judge condemns wrongful acts, but does not hate them.", source: "Seneca, On Anger, I.16 (tr. Basore)"),
        Quote(text: "While we are among human beings, let us cherish humanity.", source: "Seneca, On Anger, III.43 (tr. Basore)"),
        Quote(text: "He who fears death will never do anything worthy of a man who is alive.", source: "Seneca, On Tranquillity of Mind, 11 (tr. Basore)"),
        Quote(text: "Fire tests gold, misfortune brave men.", source: "Seneca, On Providence, 5 (tr. Basore)"),
        Quote(text: "There is a limit to the time assigned you, and if you don't use it to free yourself it will be gone and never return.", source: "Marcus Aurelius, Meditations, II.4 (tr. Hays)"),
        Quote(text: "Though thou shouldst be going to live three thousand years, and as many times ten thousand years, still remember that no man loses any other life than this which he now lives, nor lives any other than this which he now loses.", source: "Marcus Aurelius, Meditations, II.14 (tr. Long)"),
        Quote(text: "A man then must stand erect, not be kept erect by others.", source: "Marcus Aurelius, Meditations, III.5 (tr. Long)"),
        Quote(text: "Never value anything as profitable to thyself which shall compel thee to break thy promise, to lose thy self-respect.", source: "Marcus Aurelius, Meditations, III.7 (tr. Long)"),
        Quote(text: "For nowhere either with more quiet or more freedom from trouble does a man retire than into his own soul.", source: "Marcus Aurelius, Meditations, IV.3 (tr. Long)"),
        Quote(text: "The universe is transformation: life is opinion.", source: "Marcus Aurelius, Meditations, IV.3 (tr. Long)"),
        Quote(text: "Do not act as if thou wert going to live ten thousand years. Death hangs over thee. While thou livest, while it is in thy power, be good.", source: "Marcus Aurelius, Meditations, IV.17 (tr. Long)"),
        Quote(text: "Time is like a river made up of the events which happen, and a violent stream; for as soon as a thing has been seen, it is carried away, and another comes in its place, and this will be carried away too.", source: "Marcus Aurelius, Meditations, IV.43 (tr. Long)"),
        Quote(text: "The things you think about determine the quality of your mind. Your soul takes on the color of your thoughts.", source: "Marcus Aurelius, Meditations, V.16 (tr. Hays)"),
        Quote(text: "Nothing happens to any man which he is not formed by nature to bear.", source: "Marcus Aurelius, Meditations, V.18 (tr. Long)"),
        Quote(text: "That which does no harm to the state, does no harm to the citizen.", source: "Marcus Aurelius, Meditations, V.22 (tr. Long)"),
        Quote(text: "The best way of avenging thyself is not to become like the wrong doer.", source: "Marcus Aurelius, Meditations, VI.6 (tr. Long)"),
        Quote(text: "If a thing is difficult to be accomplished by thyself, do not think that it is impossible for man: but if anything is possible for man and conformable to his nature, think that this can be attained by thyself too.", source: "Marcus Aurelius, Meditations, VI.19 (tr. Long)"),
        Quote(text: "Asia, Europe are corners of the universe: all the sea a drop in the universe; Athos a little clod of the universe: all the present time is a point in eternity.", source: "Marcus Aurelius, Meditations, VI.36 (tr. Long)"),
        Quote(text: "Adapt thyself to the things with which thy lot has been cast: and the men among whom thou hast received thy portion, love them, but do it truly, sincerely.", source: "Marcus Aurelius, Meditations, VI.39 (tr. Long)"),
        Quote(text: "That which is not good for the swarm, neither is it good for the bee.", source: "Marcus Aurelius, Meditations, VI.54 (tr. Long)"),
        Quote(text: "Never let the future disturb you. You will meet it, if you have to, with the same weapons of reason which today arm you against the present.", source: "Marcus Aurelius, Meditations, VII.8 (tr. Staniforth)"),
        Quote(text: "Near is thy forgetfulness of all things; and near the forgetfulness of thee by all.", source: "Marcus Aurelius, Meditations, VII.21 (tr. Long)"),
        Quote(text: "Look within. Within is the fountain of good, and it will ever bubble up, if thou wilt ever dig.", source: "Marcus Aurelius, Meditations, VII.59 (tr. Long)"),
        Quote(text: "The art of life is more like the wrestler's art than the dancer's, in respect of this, that it should stand ready and firm to meet onsets which are sudden and unexpected.", source: "Marcus Aurelius, Meditations, VII.61 (tr. Long)"),
        Quote(text: "It is a ridiculous thing for a man not to fly from his own badness, which is indeed possible, but to fly from other men's badness, which is impossible.", source: "Marcus Aurelius, Meditations, VII.71 (tr. Long)"),
        Quote(text: "Men exist for the sake of one another. Teach them then or bear with them.", source: "Marcus Aurelius, Meditations, VIII.59 (tr. Long)"),
        Quote(text: "No longer talk at all about the kind of man that a good man ought to be, but be such.", source: "Marcus Aurelius, Meditations, X.16 (tr. Long)"),
        Quote(text: "If it is not right, do not do it: if it is not true, do not say it.", source: "Marcus Aurelius, Meditations, XII.17 (tr. Long)"),
        Quote(text: "Thou hast forgotten this too, that everything is opinion; and this, that every man lives the present time only, and loses only this.", source: "Marcus Aurelius, Meditations, XII.26 (tr. Long)"),
        Quote(text: "Men are disturbed not by things, but by the principles and notions which they form concerning things.", source: "Epictetus, Enchiridion, 5 (tr. Carter)"),
        Quote(text: "It is the act of an ill-instructed man to blame others for his own bad condition; it is the act of one who has begun to be instructed, to lay the blame on himself; and of one whose instruction is completed, neither to blame another, nor himself.", source: "Epictetus, Enchiridion, 5 (tr. Long)"),
        Quote(text: "Seek not that the things which happen should happen as you wish; but wish the things which happen to be as they are, and you will have a tranquil flow of life.", source: "Epictetus, Enchiridion, 8 (tr. Long)"),
        Quote(text: "Remember that it is not he who reviles you or strikes you, who insults you, but it is your opinion about these things as being insulting.", source: "Epictetus, Enchiridion, 20 (tr. Long)"),
        Quote(text: "Every thing has two handles, the one by which it may be borne, the other by which it may not.", source: "Epictetus, Enchiridion, 43 (tr. Carter)"),
        Quote(text: "No great thing is produced suddenly, since not even the bunch of grapes or the fig is. If you say to me now that you want a fig, I will answer to you that it requires time.", source: "Epictetus, Discourses, I.15 (tr. Long)"),
        Quote(text: "Practice yourself, for heaven's sake, in little things; and thence proceed to greater.", source: "Epictetus, Discourses, I.18"),
        Quote(text: "For it is not death or pain that is to be feared, but the fear of pain or death.", source: "Epictetus, Discourses, II.1"),
        Quote(text: "What is the first business of one who practices philosophy? To get rid of self-conceit. For it is impossible for anyone to begin to learn that which he thinks he already knows.", source: "Epictetus, Discourses, II.17"),
        Quote(text: "Every habit and faculty is confirmed and strengthened by the corresponding actions, that of walking by walking, that of running by running. If you would be a good reader, read; if a writer, write.", source: "Epictetus, Discourses, II.18"),
        Quote(text: "First say to yourself what you would be; and then do what you have to do.", source: "Epictetus, Discourses, III.23"),
        Quote(text: "Little is needed to ruin and upset everything, only a slight aberration from reason.", source: "Epictetus, Discourses, IV.3"),
    ]
}
